class NameOfAllah {
  final int id;
  final String name;
  final String meaning;
  final String supplication;

  const NameOfAllah({
    required this.id,
    required this.name,
    required this.meaning,
    required this.supplication,
  });
}

class NamesOfAllahData {
  static const List<NameOfAllah> names = [
    NameOfAllah(id: 1, name: "اللَّه", meaning: "الاسم العلم الأعظم الذي يتضمن كل صفات الكمال والجلال.", supplication: "يا الله، اهدني وسددني وثبت قلبي على دينك."),
    NameOfAllah(id: 2, name: "الرَّحْمَن", meaning: "كثير الرحمة الواسعة لجميع خلقه في الدنيا.", supplication: "يا رحمن، ارحمني برحمتك الواسعة التي وسعت كل شيء."),
    NameOfAllah(id: 3, name: "الرَّحِيم", meaning: "المنعم بالرحمة الخاصة بعباده المؤمنين في الآخرة.", supplication: "يا رحيم، ارحم ضعفي واغفر ذنبي واجعلني من عبادك الصالحين."),
    NameOfAllah(id: 4, name: "الْمَلِك", meaning: "صاحب الملك والمالك لجميع الأشياء، التصرف الكامل فيها.", supplication: "يا ملك، مالك الملك، ارزقني القناعة واصلح لي شأني كله."),
    NameOfAllah(id: 5, name: "الْقُدُّوس", meaning: "المنزه عن كل عيب ونقص، الطاهر من كل شوائب.", supplication: "يا قدوس، طهر قلبي من النفاق وعملي من الرياء."),
    NameOfAllah(id: 6, name: "السَّلاَم", meaning: "السالم من العيوب والنقائص، المفيض السلام والأمان على خلقه.", supplication: "اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام."),
    NameOfAllah(id: 7, name: "الْمُؤْمِن", meaning: "المصدق لرسله والوافي بوعده، المأمون من ظلمه.", supplication: "يا مؤمن، آمن روعاتي واجعلني آمناً يوم الفزع الأكبر."),
    NameOfAllah(id: 8, name: "الْمُهَيْمِن", meaning: "الرقيب الشاهد على كل شيء، الحافظ والمسيطر على عباده.", supplication: "يا مهيمن، احفظني بحفظك واحرصني بعينك التي لا تنام."),
    NameOfAllah(id: 9, name: "الْعَزِيز", meaning: "القوي الذي لا يغلب، الغالب على أمره.", supplication: "يا عزيز، أعزني بطاعتك ولا تذلني بمعصيتك."),
    NameOfAllah(id: 10, name: "الْجَبَّار", meaning: "الذي يجبر الكسير ويغني الفقير، ويجبر خلقه على ما يشاء.", supplication: "يا جبار، اجبر كسري واصلح حالي وفرج همي."),
    NameOfAllah(id: 11, name: "الْمُتَكَبِّر", meaning: "المنفرد بالعظمة والكبرياء، المتنزّه عن صفات الخلق.", supplication: "يا متكبر، أعذني من الكبر والعجب واجعلني خاضعاً لعظمتك."),
    NameOfAllah(id: 12, name: "الْخَالِق", meaning: "المبدع الموجد لكل شيء من العدم على غير مثال سابق.", supplication: "يا خالق، يا من خلقتني في أحسن تقويم، احفظ جوارحي في طاعتك."),
    NameOfAllah(id: 13, name: "الْبَارِئ", meaning: "الذي خلق الخلق مميزين بعضهم عن بعض دون تفاوت.", supplication: "يا بارئ، تبرأت إليك من حولي وقوتي وألجأت ظهري إليك."),
    NameOfAllah(id: 14, name: "الْمُصَوِّر", meaning: "الذي يعطي كل مخلوق صورته الهيئة والشكلي الحكيم.", supplication: "يا مصور، حسّن خُلقي كما حسّنت خَلقي."),
    NameOfAllah(id: 15, name: "الْغَفَّار", meaning: "الذي يستر الذنوب ويتجاوز عن السيئات مراراً وتكراراً.", supplication: "يا غفار، اغفر لي ذنوبي كلها دقيقها وجليلها أولها وآخرها."),
    NameOfAllah(id: 16, name: "الْقَهَّار", meaning: "الغالب الذي خضعت له الرقاب وعنت له الوجوه.", supplication: "يا قهار، اقهر عدوي واقهر شهوتي ونفسي الأمارة بالسوء."),
    NameOfAllah(id: 17, name: "الْوَهَّاب", meaning: "الذي يجود بالنعم الكثيرة بغير عوض ولا مقابل.", supplication: "يا وهاب، هب لي من لدنك رحمة وهب لي ذريتك طيبة."),
    NameOfAllah(id: 18, name: "الرَّزَّاق", meaning: "الخالق للرزق والفيّاض به على كل الكائنات.", supplication: "يا رزاق، ارزقني رزقاً حلالاً طيباً مباركاً فيه."),
    NameOfAllah(id: 19, name: "الْفَتَّاح", meaning: "الذي يفتح أبواب الرحمة والرزق وينصر عباده بالحق.", supplication: "يا فتاح، افتح لي أبواب خيرك ورحمتك وفرجك."),
    NameOfAllah(id: 20, name: "الْعَلِيم", meaning: "الذي أحاط علمه بالظواهر والبواطن، ولا يخفى عليه شيء.", supplication: "يا عليم، علمني ما ينفعني وانفعني بما علمتني وزدني علماً."),
    NameOfAllah(id: 21, name: "الْقَابِض", meaning: "الذي يضيق الرزق أو يمسك الأرواح بحكمته.", supplication: "يا قابض، باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب."),
    NameOfAllah(id: 22, name: "الْبَاسِط", meaning: "الذي يوسع الرزق وينشر الرحمة على عباده بفضله.", supplication: "يا باسط، ابسط عليّ من بركاتك ورحمتك وفضلك ورزقك."),
    NameOfAllah(id: 23, name: "الْخَافِض", meaning: "الذي يخفض الجبارين والمسرفين بذنوبهم.", supplication: "يا خافض، اخفض مقام كل ظالم ولا تجعل للظالمين عليّ سبيلاً."),
    NameOfAllah(id: 24, name: "الرَّافِع", meaning: "الذي يرفع أولياءه بالطاعة والإيمان في الدنيا والآخرة.", supplication: "يا رافع، ارفع درجاتي في الميزان واجعلني في أعلى عليين."),
    NameOfAllah(id: 25, name: "الْمُعِزّ", meaning: "الذي يعز من يشاء بالطاعة والتقوى والقناعة.", supplication: "يا معز، أعزني بالإسلام واعز الإسلام بنا."),
    NameOfAllah(id: 26, name: "الْمُذِلّ", meaning: "الذي يذل أعداءه بالمعصية والخزي والخذلان.", supplication: "يا مذل، لا تذلني بين خلقك ولا تجعلني شامتاً لأعدائي."),
    NameOfAllah(id: 27, name: "السَّمِيع", meaning: "الذي يسمع كل الأصوات والمناجاة ولا يشغله صوت عن صوت.", supplication: "يا سميع الدعاء، استجب دعائي ولا تردني خائباً."),
    NameOfAllah(id: 28, name: "الْبَصِير", meaning: "الذي يبصر كل شيء ولا يخفى عليه خافية في الأرض ولا في السماء.", supplication: "يا بصير، اجعلني ممن يخشاك كأنه يراك."),
    NameOfAllah(id: 29, name: "الْحَكَم", meaning: "القاضي العدل الذي لا يجور في حكمه مطلقاً.", supplication: "يا حكم، احكم بيني وبين خصومي بالحق وأنت خير الحاكمين."),
    NameOfAllah(id: 30, name: "الْعَدْل", meaning: "الذي يعطي كل ذي حق حقه بغير ظلم ولا حيف.", supplication: "يا عدل، عاملنا بفضلك ورحمتك ولا تعاملنا بعدلك وجزائك."),
    NameOfAllah(id: 31, name: "الَّطِيف", meaning: "البر بعباده والرفيق بهم، الموصل للخير بطرق خفية.", supplication: "يا لطيف، ألطف بي في قضائك واجعل عاقبة أمري خيراً."),
    NameOfAllah(id: 32, name: "الْخَبِير", meaning: "الذي يعلم خفايا الأمور ودقائق الأشياء.", supplication: "يا خبير، اعلم بحالي وحاجتي واكفني ما أهمني."),
    NameOfAllah(id: 33, name: "الْحَلِيم", meaning: "الذي لا يعاجل بالعقوبة بل يمهل عباده ليتوبوا.", supplication: "يا حليم، لا تعاجلني بذنوبي وارزقني التوبة النصوح."),
    NameOfAllah(id: 34, name: "الْعَظِيم", meaning: "الكبير الذي لا تعظمه الأعظام الموصوف بصفات الجلال.", supplication: "يا عظيم، عظم محبة دينك في قلبي ووفقني لمرضاتك."),
    NameOfAllah(id: 35, name: "الْغَفُور", meaning: "كثير المغفرة والستر لعباده التائبين.", supplication: "يا غفور، فاغفر لي مغفرة من عندك وارحمني."),
    NameOfAllah(id: 36, name: "الشَّكُور", meaning: "الذي يثيب على العمل القليل بال أجر الجزيل.", supplication: "يا شكور، تقبل مني يسير عملي واجعل ثوابه كبيراً."),
    NameOfAllah(id: 37, name: "الْعَلِيّ", meaning: "الرفيع القادر فوق كل خلقه بذاته وصفاته.", supplication: "يا علي، ارفع مقامي بعلم ينفع وعمل صالح يُقبل."),
    NameOfAllah(id: 38, name: "الْكَبِير", meaning: "العظيم في ذاته وصفاته، أكبر من كل شيء.", supplication: "الله أكبر كبيراً والحمد لله كثيراً وسبحان الله بكرة وأصيلاً."),
    NameOfAllah(id: 39, name: "الْحَفِيظ", meaning: "الذي يحفظ كل شيء وأعمال العباد ولا ينسى.", supplication: "يا حفيظ، احفظني من بين يدي ومن خلفي وعن يميني وعن شمالي."),
    NameOfAllah(id: 40, name: "الْمُقِيت", meaning: "الخالق للأقوات والموزع لها والمقتدر عليها.", supplication: "يا مقيت، ارزقني قوت يومي واكفني بحلالك عن حرامك."),
    NameOfAllah(id: 41, name: "الْحَسِيب", meaning: "الذي يكفي عباده جميع حوائجهم والمحاسب لهم.", supplication: "حسبي الله ونعم الوكيل، عليك توكلت وإليك أنبت."),
    NameOfAllah(id: 42, name: "الْجَلِيل", meaning: "الموصوف بنعوت الجلال والعظمة والكمال.", supplication: "يا ذا الجلال والإكرام، أكرمني برضاك والجنة."),
    NameOfAllah(id: 43, name: "الْكَرِيم", meaning: "الجوّاد الذي لا ينفد عطاؤه ويعطي بدون سؤال.", supplication: "يا كريم، أكرم نزلي ووسع مدخلي ولا تحرمني فضلك."),
    NameOfAllah(id: 44, name: "الرَّقِيب", meaning: "المطلع على الأحوال والضمائر والحركات والسكنات.", supplication: "يا رقيب، اعصمني من المعاصي في السّر والعلن."),
    NameOfAllah(id: 45, name: "الْمُجِيب", meaning: "الذي يجيب دعوة الداعين وسؤال السائلين.", supplication: "يا مجيب الدعوات، استجب دعائي واقضِ حاجتي."),
    NameOfAllah(id: 46, name: "الْوَاسِع", meaning: "الذي وسعت رحمته وعلمه ورحمته ورزقه كل شيء.", supplication: "يا واسع المغفرة، اغفر لي ولوالدي وللمؤمنين."),
    NameOfAllah(id: 47, name: "الْحَكِيم", meaning: "الذي يضع الأمور في مواضعها المحددة بحكمة.", supplication: "يا حكيم، وفقني لما فيه الخير والصواب في أموري."),
    NameOfAllah(id: 48, name: "الْوَدُود", meaning: "المحب لعباده الصالحين والمحبوب في قلوبهم.", supplication: "يا ودود، القِ محبتي في قلوب عبادك الصالحين."),
    NameOfAllah(id: 49, name: "الْمَجِيد", meaning: "العظيم الشريف المجد الواسع الكرم والفضل.", supplication: "يا مجيد، مجّد ذكري بالطاعة والخير في الدنيا والآخرة."),
    NameOfAllah(id: 50, name: "الْبَاعِث", meaning: "الذي يبحث الخلائق يوم القيامة للحساب والجزاء.", supplication: "يا باعث، ابعثني يوم القيامة آثناً ومستبشراً برحمتك."),
    NameOfAllah(id: 51, name: "الشَّهِيد", meaning: "الذي لا يعزب عنه شيء، الشاهد على عباده.", supplication: "يا شهيد، اشهد لي بالإيمان والتوحيد عند الموت."),
    NameOfAllah(id: 52, name: "الْحَقّ", meaning: "الموجود بغير زوال، الذي أمره ونبيه ودينه حق.", supplication: "يا حق، ثبتني على الحق واهدني إلى صراطك المستقيم."),
    NameOfAllah(id: 53, name: "الْوَكِيل", meaning: "الذي يتولى أمور عباده الكافية والمدبر لها.", supplication: "يا وكيل، توكلت عليك في كل أموري فكن لي خير وكيل."),
    NameOfAllah(id: 54, name: "الْقَوِيّ", meaning: "الذي لا يعجزه شيء وله القدرة التامة.", supplication: "يا قوي، قوّني على طاعتك والعمل بما يرضيك."),
    NameOfAllah(id: 55, name: "الْمَتِين", meaning: "الشديد القوة الذي لا تلحقه مشقة في أفعاله.", supplication: "يا متين، ثبت أقدامي وزدني ثباتاً في الدين."),
    NameOfAllah(id: 56, name: "الْوَلِيّ", meaning: "الناصر لعباده المؤمنين والمحب والمحبوب لهم.", supplication: "يا ولي، تولني فيمن توليت وعافني فيمن عافيت."),
    NameOfAllah(id: 57, name: "الْحَمِيد", meaning: "المحمود على كل حال وفي كل وقت ولحظة.", supplication: "يا حميد، لك الحمد حتى ترضى ولك الحمد إذا رضيت."),
    NameOfAllah(id: 58, name: "الْمُحْصِي", meaning: "الذي أحصى كل شيء بعلمه وعدد الذرات والأنفاس.", supplication: "يا محصي، لا تحصِ عليّ عيوبي واغفر لي ما قدمت وما أخرت."),
    NameOfAllah(id: 59, name: "الْمُبْدِئ", meaning: "الذي بدأ خلق الخلائق أول مرة من غير شيء.", supplication: "يا مبدئ، ابدأ لي بأمر خير واجعل عاقبته الفلاح."),
    NameOfAllah(id: 60, name: "الْمُعِيد", meaning: "الذي يعيد الخلائق بعد موتهم وفنائهم للحساب.", supplication: "يا معيد، أعد عليّ النعم واجعل عودتي إليك عودة نصوحاً."),
    NameOfAllah(id: 61, name: "الْمُحْيِي", meaning: "الذي يحيي الأجساد والأرواح والقلوب بالإيمان.", supplication: "يا محيي، أحيِ قلبي بنور معرفتك وطاعتك."),
    NameOfAllah(id: 62, name: "الْمُمِيت", meaning: "الذي يميت الأحياء بكتل آجالهم الحكيمة.", supplication: "يا مميت، أمتني على الإيمان والتوحيد غير خزايا ولا مفتونين."),
    NameOfAllah(id: 63, name: "الْحَيّ", meaning: "الدائم الباقي الذي لا يموت ولا يزول.", supplication: "يا حي يا قيوم، برحمتك أستغيث أصلح لي شأني كله."),
    NameOfAllah(id: 64, name: "الْقَيُّوم", meaning: "القائم بنفسه المقيم لغيره من جميع المخلوقات.", supplication: "يا قيوم، أقم لي أمري كله ولا تكلني إلى نفسي طرفة عين."),
    NameOfAllah(id: 65, name: "الْوَاجِد", meaning: "الذي لا يعوزه شيء، الظافر بكل ما يريد.", supplication: "يا واجد، ارزقني الوجدان والرضا بما قسمت لي."),
    NameOfAllah(id: 66, name: "الْمَاجِد", meaning: "الواسع الكرم العظيم الشرف والفضل.", supplication: "يا ماجد، أفرغ عليّ صبراً وتوفني مع الأبرار."),
    NameOfAllah(id: 67, name: "الْواحِد", meaning: "المتنزه عن الشريك والتركيب والشبيه.", supplication: "يا واحد يا أحد، يا من لم يلد ولم يولد ولم يكن له كفواً أحد."),
    NameOfAllah(id: 68, name: "الصَّمَد", meaning: "الذي تقصده الخلائق في جميع الحوائج والضرورات.", supplication: "يا صمد، صمدت إليك بحاجتي وافتقاري فاقضها لي."),
    NameOfAllah(id: 69, name: "الْقَادِر", meaning: "المقتدر الذي إذا أراد شيئاً قال له كن فيكون.", supplication: "يا قادر، أنت القادر على فرج همي فافرج عني."),
    NameOfAllah(id: 70, name: "الْمُقْتَدِر", meaning: "البالغ التمام في القدرة والسيطرة.", supplication: "يا مقتدر، قدر لي الخير حيث كان ثم رضني به."),
    NameOfAllah(id: 71, name: "الْمُقَدِّم", meaning: "الذي يقدم الأشياء في مواضعها بحكمته.", supplication: "يا مقدم، قدم لي في الخير ولا تؤخرني عن العبادة."),
    NameOfAllah(id: 72, name: "الْمُؤَخِّر", meaning: "الذي يؤخر ما يشاء من الأمور لحكمة صائبة.", supplication: "يا مؤخر، باعد بيني وبين الذنوب والآثام."),
    NameOfAllah(id: 73, name: "الأَوَّل", meaning: "الذي ليس قبله شيء وهو قبل كل خلق.", supplication: "يا أول، أنت الأول فليس قبلك شيء فلك الحمد."),
    NameOfAllah(id: 74, name: "الأَخِر", meaning: "الباقي بعد فناء الخلائق والذي ليس بعده شيء.", supplication: "يا آخر، اجعل خير عمري آخره وخير عملي خواتيمه."),
    NameOfAllah(id: 75, name: "الظَّاهِر", meaning: "الذي ظهر بعظمته وآياته العالية المتنوعة.", supplication: "يا ظاهر، اظهر الحق وازهق الباطل."),
    NameOfAllah(id: 76, name: "الْبَاطِن", meaning: "الذي خفي على الأبصار وأحاط بكل باطن وسر.", supplication: "يا باطن، طهر باطني وسريرتي واجعلها خيراً من علانيتي."),
    NameOfAllah(id: 77, name: "الْوَالِي", meaning: "المالك المتصرف المدبر لأمور خلقه.", supplication: "يا والي، تولّ أصل شأني ولا تكلني إلى خلقه."),
    NameOfAllah(id: 78, name: "الْمُتَعَالِي", meaning: "المنزه عن صفات المخلوقين المتعالي عن كل نقص.", supplication: "يا متعالي، تباركت وتعاليت يا ذا الجلال والإكرام."),
    NameOfAllah(id: 79, name: "الْبَرّ", meaning: "العطوف المحسن بعباده الواسع العطاء.", supplication: "يا بر، يا محسن، أحسن إليّ بفضلك وإحسانك."),
    NameOfAllah(id: 80, name: "التَّوَّاب", meaning: "الذي يقبل توبة عباده ويبدل سيئاتهم حسنات.", supplication: "يا تواب، تب عليّ إنك أنت التواب الرحيم."),
    NameOfAllah(id: 81, name: "الْمُنْتَقِم", meaning: "الذي يعاقب العصاة والظلمة بالعدل.", supplication: "يا منتقم، انتصر لنا من الظالمين ولا تسلطهم علينا."),
    NameOfAllah(id: 82, name: "العَفُوّ", meaning: "الذي يمحو السيئات والتجاوز عن الذنوب.", supplication: "اللهم إنك عفو تحب العفو فاعفُ عني."),
    NameOfAllah(id: 83, name: "الرَّؤُوف", meaning: "الشديد الرحمة بالعباد والعطف عليهم.", supplication: "يا رؤوف، ارأف بي في جميع أموري ويسرها لي."),
    NameOfAllah(id: 84, name: "مَالِكُ الْمُلْك", meaning: "الذي يتي الملك من يشاء وينزعه ممن يشاء.", supplication: "قل اللهم مالك الملك تؤتي الملك من تشاء وتنزع الملك ممن تشاء."),
    NameOfAllah(id: 85, name: "ذُو الْجَلاَلِ وَالإِكْرَام", meaning: "المستحق لجميع معاني العظمة والكرم والجود.", supplication: "يا ذا الجلال والإكرام، ثبت قلبي على طاعتك."),
    NameOfAllah(id: 86, name: "الْمُقْسِط", meaning: "العادل الذي ينصف المظلوم من الظالم.", supplication: "يا مقسط، أنصفني واجعلني عادلاً في قولي وعملي."),
    NameOfAllah(id: 87, name: "الْجَامِع", meaning: "الذي يجمع الخلائق يوم القيامة للحساب.", supplication: "يا جامع الناس ليوم لا ريب فيه اجمع بيني وبين الخير."),
    NameOfAllah(id: 88, name: "الْغَنِيّ", meaning: "الذي لا يحتاج إلى أحد وكل الخلق مفتقرون إليه.", supplication: "يا غني، أغنني بفضلك وبحلالك عن حرامك."),
    NameOfAllah(id: 89, name: "الْمُغْنِي", meaning: "الذي يسد فقر عباده ويفيض عليهم من رزقه.", supplication: "يا مغني، أغنِ فقري وافتح لي أبواب رزقك."),
    NameOfAllah(id: 90, name: "الْمَانِع", meaning: "الذي يمنع البلاء عن عباده ويمنع عطاءه لحكمة.", supplication: "يا مانع، امنع عني كل شر وبلية ومرض."),
    NameOfAllah(id: 91, name: "الضَّارّ", meaning: "الذي يبتلي من يشاء بالضر لحكمة وتطهير.", supplication: "يا ضار يا نافع، أعوذ بك من الضر والشرور."),
    NameOfAllah(id: 92, name: "النَّافِع", meaning: "الذي يوصل النفع والخير لكل من يشاء من عباده.", supplication: "يا نافع، انفعني بالقرآن العظيم واجعله شفيعاً لي."),
    NameOfAllah(id: 93, name: "النُّور", meaning: "الهادي المرشد الذي أنار السموات والأرض.", supplication: "يا نور، نور قلبي بنور هدايتك وطاعتك."),
    NameOfAllah(id: 94, name: "الْهَادِي", meaning: "الذي يهدي عباده إلى الصراط المستقيم بفضله.", supplication: "يا هادي، اهدني واهدِ بي واجعلني سبباً لمن اهتدى."),
    NameOfAllah(id: 95, name: "الْبَدِيع", meaning: "الذي أبدع الخلق على غير مثال سابق بغير طراز.", supplication: "يا بديع السموات والأرض، ابدع لي فرجاً من حيث لا أحتسب."),
    NameOfAllah(id: 96, name: "الْبَاقِي", meaning: "الدائم الوجود بغير نهاية بعد فناء الخلق.", supplication: "يا باقي، أنت الباقي وكل شيء هالك إلا وجهك."),
    NameOfAllah(id: 97, name: "الْوَارِث", meaning: "الباقي بعد فناء جميع الخلائق والمالك الحقيقي.", supplication: "يا وارث، ارزقني من لدنك علماً وارثاً نافعاً."),
    NameOfAllah(id: 98, name: "الرَّشِيد", meaning: "المستغني عن مرشد، الذي يرشد خلقه بالحق.", supplication: "يا رشيد، أرشدني لأحب الأعمال والأقوال إليك."),
    NameOfAllah(id: 99, name: "الصَّبُور", meaning: "الذي لا يعاجل العصاة بالعقوبة بل يصبر عليهم.", supplication: "يا صبور، أفرغ عليّ صبراً وتوفني مسلماً."),
  ];
}
